// src/services/marketHighlightsService.ts
var MarketHighlightsService = {
  /**
   * Build highlights directly from HistoricalDataRepository (Server / Node.js tests)
   */
  buildFromRepository(exchange = "NSE", limit = 5) {
    const stats = SecurityMaster.getStats();
    const catalogueCount = exchange === "NSE" ? stats.nseCount : stats.bseCount;
    const safeLimit = Math.max(1, Math.min(25, Math.floor(limit) || 5));
    const { latestDate, rows } = HistoricalDataRepository.getLatestSessionHighlightsRaw(exchange);
    if (!latestDate || rows.length === 0) {
      return {
        exchange,
        catalogueCount,
        latestDate: null,
        previousDate: null,
        evaluatedCount: 0,
        isHistoricalEOD: true,
        gainers: [],
        losers: [],
        mostActive: []
      };
    }
    const prevDateCounts = /* @__PURE__ */ new Map();
    const items = rows.map((row) => {
      const secMeta = SecurityMaster.getBySymbol(row.symbol, exchange);
      const name = secMeta?.name || row.companyName || row.symbol;
      const sector = secMeta?.sector || "Diversified";
      let dailyChange = null;
      let dailyChangePercent = null;
      if (row.prevSessionClose !== null && row.prevSessionClose > 0) {
        dailyChange = Number((row.closePrice - row.prevSessionClose).toFixed(2));
        dailyChangePercent = Number(
          ((row.closePrice - row.prevSessionClose) / row.prevSessionClose * 100).toFixed(2)
        );
      }
      if (row.prevSessionDate) {
        prevDateCounts.set(row.prevSessionDate, (prevDateCounts.get(row.prevSessionDate) || 0) + 1);
      }
      return {
        exchange: row.exchange,
        symbol: row.symbol,
        name,
        sector,
        tradeDate: row.tradeDate,
        prevTradeDate: row.prevSessionDate,
        closePrice: row.closePrice,
        prevClosePrice: row.prevSessionClose,
        dailyChange,
        dailyChangePercent,
        volume: row.volume,
        dataSource: row.dataSource
      };
    });
    let previousDate = null;
    let maxPrevCount = -1;
    for (const [dt, count] of prevDateCounts.entries()) {
      if (count > maxPrevCount || count === maxPrevCount && previousDate && dt > previousDate) {
        maxPrevCount = count;
        previousDate = dt;
      }
    }
    const gainers = items.filter((item) => item.dailyChangePercent !== null && item.dailyChangePercent > 0).sort((a, b) => {
      const diff = (b.dailyChangePercent ?? 0) - (a.dailyChangePercent ?? 0);
      return diff !== 0 ? diff : b.volume - a.volume;
    }).slice(0, safeLimit);
    const losers = items.filter((item) => item.dailyChangePercent !== null && item.dailyChangePercent < 0).sort((a, b) => {
      const diff = (a.dailyChangePercent ?? 0) - (b.dailyChangePercent ?? 0);
      return diff !== 0 ? diff : b.volume - a.volume;
    }).slice(0, safeLimit);
    const mostActive = items.filter((item) => item.volume > 0).sort((a, b) => b.volume - a.volume).slice(0, safeLimit);
    return {
      exchange,
      catalogueCount,
      latestDate,
      previousDate,
      evaluatedCount: items.length,
      isHistoricalEOD: true,
      gainers,
      losers,
      mostActive
    };
  },
  /**
   * Fetch genuine EOD market highlights from the Node/SQLite backend API (Browser runtime)
   */
  async fetchMarketHighlights(exchange = "NSE", limit = 5, signal) {
    const params = new URLSearchParams({
      exchange,
      limit: String(limit)
    });
    const response = await fetch(`/api/market/highlights?${params.toString()}`, {
      method: "GET",
      headers: { Accept: "application/json" },
      signal
    });
    if (!response.ok) {
      let message = `Unable to load ${exchange} market highlights (HTTP ${response.status}).`;
      try {
        const body = await response.json();
        if (body?.error) message = body.error;
      } catch {
      }
      throw new Error(message);
    }
    return await response.json();
  }
};

// server.ts
dotenv.config();
var app = express();
var PORT = parseInt(process.env.PORT || "3000", 10);
var ai = new GoogleGenAI({
  apiKey: process.env.GEMINI_API_KEY,
  httpOptions: {
    headers: {
      "User-Agent": "aistudio-build"
    }
  }
});
app.use(express.json({ limit: "10mb" }));
app.get("/api/market/highlights", (req, res) => {
  try {
    const rawExchange = String(req.query.exchange || "NSE").trim().toUpperCase();
    if (rawExchange !== "NSE" && rawExchange !== "BSE") {
      return res.status(400).json({ error: "Invalid exchange parameter. Expected NSE or BSE." });
    }
    const exchange = rawExchange;
    const rawLimit = parseInt(String(req.query.limit || "5"), 10);
    const limit = Number.isFinite(rawLimit) ? Math.min(25, Math.max(1, rawLimit)) : 5;
    const highlights = MarketHighlightsService.buildFromRepository(exchange, limit);
    return res.json(highlights);
  } catch (err) {
    console.error("Error in /api/market/highlights:", err);
    return res.status(500).json({
      error: err?.message || "Failed to query historical market highlights"
    });
  }
});
app.post("/api/gemini/chat", async (req, res) => {
  try {
    const {
      messages,
      model = "gemini-3.8-flash",
      role = "analyst",
      stockContext
    } = req.body;
    if (!messages || !Array.isArray(messages) || messages.length === 0) {
      return res.status(400).json({ error: "Messages array is required" });
    }
    if (!process.env.GEMINI_API_KEY) {
      return res.status(503).json({
        error: "GEMINI_API_KEY is not configured on the server. Please ensure an API key is attached in Settings > Secrets."
      });
    }
    let roleInstruction = "";
    switch (role) {
      case "deep-researcher":
        roleInstruction = `You are an elite Equity Research Analyst specializing in Indian Equities (NSE and BSE).
Your role is deep reasoning, fundamental valuation, balance sheet health, moat analysis, corporate governance, and macro-tailwinds.
Provide thorough, well-reasoned, quantitative breakdowns. Reference specific metrics (P/E, ROCE, Debt-to-Equity, FII/DII holdings) where appropriate.`;
        break;
      case "technical-strategist":
        roleInstruction = `You are a Quantitative Technical Analyst specializing in Indian Equities (NSE/BSE).
Your role is multi-timeframe chart pattern analysis, support/resistance levels, moving average crossovers (20/50/200 EMA), momentum oscillators (RSI, MACD), and risk-to-reward ratios.
Offer objective, structured risk-managed insights with defined entry zones, target levels, and invalidation stop-losses.`;
        break;
      case "market-tutor":
        roleInstruction = `You are a patient and knowledgeable Academic Finance Professor and Stock Market Tutor for engineering and finance students at REVA University.
Explain financial concepts, algorithmic trading models (Ridge Regression, Random Forest, Decision Trees), market microstructure (Bhavcopy, UDiFF, SEBI surveillance BE/BZ segments), and technical indicators clearly with illustrative examples.`;
        break;
      case "fast-assistant":
      default:
        roleInstruction = `You are an intelligent, prompt, and helpful Indian Stock Market Assistant on the NSE-BSE Market Analyzer platform.
Provide concise, accurate answers on stock symbols, price movements, exchange differences (NSE vs BSE), indices, and quick stock overviews.`;
        break;
    }
    let systemInstruction = `${roleInstruction}

Platform Context:
- Platform: Intelligent NSE-BSE Market Analyzer (B.Tech Capstone Project).
- Universe: 8,950+ NSE & BSE securities, including Mainboard & BSE SME segments.
- Data: Authentic EOD Bhavcopy records from official exchange archives (2024 to 2026).
- Standard Academic Disclaimer: You provide educational quantitative and market insights, not SEBI-registered financial advisory or guaranteed stock tips. Always encourage proper risk management.`;
    if (stockContext && stockContext.symbol) {
      systemInstruction += `

Currently Viewed Stock Context:
- Symbol: ${stockContext.symbol} (${stockContext.exchange || "NSE"})
- Company: ${stockContext.name || stockContext.symbol}
- Sector: ${stockContext.sector || "N/A"}
- LTP: \u20B9${stockContext.ltp ?? "N/A"} (${stockContext.changePercent ? (stockContext.changePercent > 0 ? "+" : "") + stockContext.changePercent.toFixed(2) + "%" : "N/A"})
- P/E Ratio: ${stockContext.peRatio ?? "N/A"}`;
    }
    const contents = messages.map((m) => ({
      role: m.role === "user" ? "user" : "model",
      parts: [{ text: m.text }]
    }));
    const response = await ai.models.generateContent({
      model,
      contents,
      config: {
        systemInstruction
      }
    });
    const replyText = response.text || "I analyzed your request, but no text response was generated.";
    return res.json({
      text: replyText,
      modelUsed: model,
      role
    });
  } catch (err) {
    console.error("Error in /api/gemini/chat:", err);
    return res.status(500).json({
      error: err?.message || "Failed to generate response from Gemini API"
    });
  }
});
async function startServer() {
  if (process.env.NODE_ENV === "production") {
    const distPath = path.resolve(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (_req, res) => {
      res.sendFile(path.resolve(distPath, "index.html"));
    });
  } else {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa"
    });
    app.use(vite.middlewares);
  }
  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server listening on http://0.0.0.0:${PORT}`);
  });
}
startServer().catch((err) => {
  console.error("Failed to start server:", err);
  process.exit(1);
});
